AssistantMessageToolRequest(name='create', tool_call_id='function-call-02ba50cd-8f59-4a43-be3e-661208e1e1aa', arguments={'file_text': ':root {
    --primary: #111111;
    --secondary: #4a4a4a;
    --background: #ffffff;
    --surface: #f4f4f4;
    --accent: #d32f2f;
    --focus: #005fcc;
    --text-main: #111111;
    --text-muted: #666666;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: var(--text-main);
    background: var(--background);
    line-height: 1.5;
}

a {
    color: var(--primary);
    text-decoration: none;
}

a:focus, button:focus {
    outline: 3px solid var(--focus);
    outline-offset: 2px;
}

.skip-link {
    position: absolute;
    top: -60px;
    left: 0;
    background: var(--primary);
    color: white;
    padding: 12px 24px;
    z-index: 100;
    font-weight: bold;
    transition: top 0.2s;
}

.skip-link:focus {
    top: 0;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 24px;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* Header */
.site-header {
    border-bottom: 1px solid #eaeaea;
    padding: 20px 0;
    background: white;
    position: sticky;
    top: 0;
    z-index: 10;
}

.header-inner {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo a {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: -0.5px;
}

.nav-links {
    list-style: none;
    display: flex;
    gap: 32px;
}

.nav-links a {
    font-weight: 500;
    color: var(--text-main);
}

.nav-links a:hover, .nav-links a:focus {
    text-decoration: underline;
    text-underline-offset: 4px;
}

.cart-btn {
    background: none;
    border: none;
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 12px;
}

/* Main content */
main {
    padding-bottom: 64px;
}

section {
    padding-top: 64px;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 32px;
}

.section-title {
    font-size: 2rem;
    font-weight: 700;
    line-height: 1.2;
}

.view-all {
    font-weight: 500;
    text-decoration: underline;
    text-underline-offset: 4px;
}

/* Grids */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 32px;
}

.product-card {
    display: flex;
    flex-direction: column;
    group: relative;
}

.product-image-container {
    position: relative;
    width: 100%;
    aspect-ratio: 3/4;
    background: var(--surface);
    margin-bottom: 16px;
    border-radius: 8px;
    overflow: hidden;
}

.product-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.product-badge {
    position: absolute;
    top: 12px;
    left: 12px;
    background: var(--accent);
    color: white;
    padding: 4px 8px;
    font-size: 0.75rem;
    font-weight: 700;
    border-radius: 4px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.product-info {
    display: flex;
    flex-direction: column;
    flex: 1;
}

.product-name {
    font-size: 1.125rem;
    font-weight: 600;
    margin-bottom: 4px;
}

/* Important for accessible clickable cards without bad HTML nesting */
.product-name a {
    text-decoration: none;
    color: var(--text-main);
}
.product-name a:hover {
    text-decoration: underline;
}
.product-name a::after {
    content: "";
    position: absolute;
    inset: 0;
}

.product-price-wrapper {
    margin-bottom: 16px;
    font-size: 1rem;
    color: var(--secondary);
}

.original-price {
    text-decoration: line-through;
    color: var(--text-muted);
    margin-right: 8px;
}

.sale-price {
    color: var(--accent);
    font-weight: 700;
}

.btn {
    display: inline-flex;
    justify-content: center;
    align-items: center;
    background: var(--primary);
    color: white;
    padding: 12px 24px;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 600;
    text-align: center;
    transition: background 0.2s;
    position: relative;
    z-index: 2; /* To sit above the clickable card link */
}

.btn:hover, .btn:focus {
    background: #333;
}

/* Editorial */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 32px;
}

.editorial-card {
    border-radius: 12px;
    overflow: hidden;
    background: var(--surface);
    display: flex;
    flex-direction: column;
}

.editorial-image {
    width: 100%;
    aspect-ratio: 16/9;
    object-fit: cover;
}

.editorial-content {
    padding: 24px;
    flex: 1;
    display: flex;
    flex-direction: column;
}

.editorial-title {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 12px;
}

.editorial-title a {
    color: var(--text-main);
}
.editorial-title a:hover {
    text-decoration: underline;
}

.editorial-excerpt {
    color: var(--secondary);
    margin-bottom: 24px;
    flex: 1;
}

.read-more {
    font-weight: 600;
    text-decoration: underline;
    text-underline-offset: 4px;
    align-self: flex-start;
}

/* Footer */
.site-footer {
    background: var(--surface);
    padding: 48px 0;
    border-top: 1px solid #eaeaea;
}

.footer-content {
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 32px;
}

.footer-section h2 {
    font-size: 1.125rem;
    margin-bottom: 16px;
}

.footer-links {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.footer-links a {
    color: var(--secondary);
}

.footer-links a:hover, .footer-links a:focus {
    color: var(--primary);
    text-decoration: underline;
}

.footer-bottom {
    margin-top: 48px;
    padding-top: 24px;
    border-top: 1px solid #ddd;
    text-align: center;
    color: var(--text-muted);
}

@media (max-width: 768px) {
    .nav-links {
        display: none;
    }

    .section-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 12px;
    }
}
